// src/store/categoryStore.js — Categories: paged / filtered / sorted server-side (generated by make:module).

import { create } from 'zustand';
import categoryApi from '../services/categories/categoryApi';

export const DEFAULT_CATEGORIES_PARAMS = { page: 1, per_page: 20, search: '', active: undefined, sort: undefined, order: undefined };

const useCategoryStore = create((set, get) => ({

  // ── State ──────────────────────────────────────────
  items:     [],
  total:     0,
  params:    DEFAULT_CATEGORIES_PARAMS,
  isLoading: false,
  error:     null,

  // ── Actions ────────────────────────────────────────
  fetchItems: async (changes = {}) => {
    const params = { ...get().params, ...changes };
    set({ params, isLoading: true, error: null });
    try {
      const { data } = await categoryApi.getAll(params);
      set({ items: data.data, total: data.meta.total });
    } catch (error) {
      set({ error: error.response?.data?.message || 'Failed to load categories.' });
    } finally {
      set({ isLoading: false });
    }
  },

}));

export default useCategoryStore;
